"""Stock keeping for a small warehouse."""


def available(stock, reserved):
    """Units available to sell."""
    return stock - reserved


def received(stock, count):
    """Stock after a delivery."""
    return stock + count


def reserved_for(stock, orders):
    """Units reserved across a list of orders."""
    return sum(order["units"] for order in orders)

